    const numberD = properties.map(value => (value != null ? Number(value) : 0));
    [
      this.$d.years,
      this.$d.months,
      this.$d.weeks,
      this.$d.days,
      this.$d.hours,
      this.$d.minutes,
      this.$d.seconds
    ] = numberD

proto.valueOf = function () {
